      "payloadProductionStatus": "blocked_needs_production_raster",
      "payloadProductionImagePath": "episodes/EP02/generated/mock_battle_production_keyframes_2026-07-17/Shot029_start.png",
      "payloadBlockedSourceImagePath": "episodes/EP02/generated/p1_mock_battle_v1/Shot029_SylvainIngridSideFlank.png",
